   1 | PJ_DEF(pj_status_t) pjmedia_rtcp_fb_build_rpsi(
   2 | 					    pjmedia_rtcp_session *session, 
   3 | 					    void *buf,
   4 | 					    pj_size_t *length,
   5 | 					    const pjmedia_rtcp_fb_rpsi *rpsi)
   6 | {
   7 |     pjmedia_rtcp_common *hdr;
   8 |     pj_uint8_t *p;
   9 |     unsigned bitlen, padlen, len;
  10 | 
  11 |     PJ_ASSERT_RETURN(session && buf && length && rpsi, PJ_EINVAL);
  12 | 
  13 |     bitlen = (unsigned)rpsi->rpsi_bit_len + 16;
  14 |     padlen = (32 - (bitlen % 32)) % 32;
  15 |     len = (3 + (bitlen+padlen)/32) * 4;
  16 |     if (len > *length)
  17 | 	return PJ_ETOOSMALL;
  18 | 
  19 |     /* Build RTCP-FB RPSI header */
  20 |     hdr = (pjmedia_rtcp_common*)buf;
  21 |     pj_memcpy(hdr, &session->rtcp_rr_pkt.common,  sizeof(*hdr));
  22 |     hdr->pt = RTCP_PSFB;
  23 |     hdr->count = 3; /* FMT = 3 */
  24 |     hdr->length = pj_htons((pj_uint16_t)(len/4 - 1));
  25 | 
  26 |     /* Build RTCP-FB RPSI FCI */
  27 |     p = (pj_uint8_t*)hdr + sizeof(*hdr);
  28 |     /* PB (number of padding bits) */
  29 |     *p++ = (pj_uint8_t)padlen;
  30 |     /* Payload type */
  31 |     *p++ = rpsi->pt & 0x7F;
  32 |     /* RPSI bit string */
  33 |     pj_memcpy(p, rpsi->rpsi.ptr, rpsi->rpsi_bit_len/8);
  34 |     p += rpsi->rpsi_bit_len/8;
  35 |     if (rpsi->rpsi_bit_len % 8) {
  36 | 	*p++ = *(rpsi->rpsi.ptr + rpsi->rpsi_bit_len/8);
  37 |     }
  38 |     /* Zero padding */
  39 |     if (padlen >= 8)
  40 | 	pj_bzero(p, padlen/8);
  41 | 
  42 |     /* Finally */
  43 |     *length = len;
  44 | 
  45 |     return PJ_SUCCESS;
  46 | }
</FUNCTION_SOURCE>

