   1 | long keyctl_read_key(key_serial_t keyid, char __user *buffer, size_t buflen)
   2 | {
   3 | 	struct key *key;
   4 | 	key_ref_t key_ref;
   5 | 	long ret;
   6 | 
   7 | 	/* find the key first */
   8 | 	key_ref = lookup_user_key(keyid, 0, 0);
   9 | 	if (IS_ERR(key_ref)) {
  10 | 		ret = -ENOKEY;
  11 | 		goto error;
  12 | 	}
  13 | 
  14 | 	key = key_ref_to_ptr(key_ref);
  15 | 
  16 | 	/* see if we can read it directly */
  17 | 	ret = key_permission(key_ref, KEY_NEED_READ);
  18 | 	if (ret == 0)
  19 | 		goto can_read_key;
  20 | 	if (ret != -EACCES)
  21 | 		goto error2;
  22 | 
  23 | 	/* we can't; see if it's searchable from this process's keyrings
  24 | 	 * - we automatically take account of the fact that it may be
  25 | 	 *   dangling off an instantiation key
  26 | 	 */
  27 | 	if (!is_key_possessed(key_ref)) {
  28 | 		ret = -EACCES;
  29 | 		goto error2;
  30 | 	}
  31 | 
  32 | 	/* the key is probably readable - now try to read it */
  33 | can_read_key:
  34 | 	ret = -EOPNOTSUPP;
  35 | 	if (key->type->read) {
  36 | 		/* Read the data with the semaphore held (since we might sleep)
  37 | 		 * to protect against the key being updated or revoked.
  38 | 		 */
  39 | 		down_read(&key->sem);
  40 | 		ret = key_validate(key);
  41 | 		if (ret == 0)
  42 | 			ret = key->type->read(key, buffer, buflen);
  43 | 		up_read(&key->sem);
  44 | 	}
  45 | 
  46 | error2:
  47 | 	key_put(key);
  48 | error:
  49 | 	return ret;
  50 | }
  51 | 
