  13 | 			struct pid *tty_pgrp = tty_get_pgrp(tty);
  14 | 			if (tty_pgrp) {
  15 | 				kill_pgrp(tty_pgrp, SIGHUP, on_exit);
  16 | 				if (!on_exit)
  17 | 					kill_pgrp(tty_pgrp, SIGCONT, on_exit);
  18 | 				put_pid(tty_pgrp);
  19 | 			}
  20 | 		}
  21 | 		tty_kref_put(tty);
  22 | 
  23 | 	} else if (on_exit) {
  24 | 		struct pid *old_pgrp;
  25 | 		spin_lock_irq(&current->sighand->siglock);
  26 | 		old_pgrp = current->signal->tty_old_pgrp;
  27 | 		current->signal->tty_old_pgrp = NULL;
  28 | 		spin_unlock_irq(&current->sighand->siglock);
  29 | 		if (old_pgrp) {
  30 | 			kill_pgrp(old_pgrp, SIGHUP, on_exit);
  31 | 			kill_pgrp(old_pgrp, SIGCONT, on_exit);
  32 | 			put_pid(old_pgrp);
  33 | 		}
  34 | 		return;
  35 | 	}
  36 | 
  37 | 	spin_lock_irq(&current->sighand->siglock);
  38 | 	put_pid(current->signal->tty_old_pgrp);
  39 | 	current->signal->tty_old_pgrp = NULL;
  40 | 
  41 | 	tty = tty_kref_get(current->signal->tty);
  42 | 	if (tty) {
  43 | 		unsigned long flags;
  44 | 		spin_lock_irqsave(&tty->ctrl_lock, flags);
  45 | 		put_pid(tty->session);
  46 | 		put_pid(tty->pgrp);
  47 | 		tty->session = NULL;
  48 | 		tty->pgrp = NULL;
  49 | 		spin_unlock_irqrestore(&tty->ctrl_lock, flags);
  50 | 		tty_kref_put(tty);
  51 | 	}
  52 | 
  53 | 	spin_unlock_irq(&current->sighand->siglock);
  54 | 	/* Now clear signal->tty under the lock */
  55 | 	read_lock(&tasklist_lock);
