  13 |                 { "ms",    USEC_PER_MSEC   },
  14 |                 { "us",    1               },
  15 |         };
  16 | 
  17 |         char *p = buf;
  18 |         bool something = false;
  19 | 
  20 |         assert(buf);
  21 |         assert(l > 0);
  22 | 
