  32 |                 return p;
  33 |         }
  34 | 
  35 |         /* The result of this function can be parsed with parse_sec */
  36 | 
  37 |         for (size_t i = 0; i < ELEMENTSOF(table); i++) {
  38 |                 int k = 0;
  39 |                 size_t n;
  40 |                 bool done = false;
