  72 |                                              "%s"USEC_FMT".%0*"PRI_USEC"%s",
  73 |                                              p > buf ? " " : "",
  74 |                                              a,
  75 |                                              j,
  76 |                                              b,
  77 |                                              table[i].suffix);
  78 | 
  79 |                                 t = 0;
  80 |                                 done = true;
  81 |                         }
  82 |                 }
  83 | 
