  11 | 	/*
  12 | 	 * After the __add_wait_queue the uwq is visible to userland
  13 | 	 * through poll/read().
  14 | 	 */
  15 | 	__add_wait_queue(&ctx->event_wqh, &ewq->wq);
  16 | 	for (;;) {
  17 | 		set_current_state(TASK_KILLABLE);
  18 | 		if (ewq->msg.event == 0)
  19 | 			break;
  20 | 		if (READ_ONCE(ctx->released) ||
  21 | 		    fatal_signal_pending(current)) {
  22 | 			/*
  23 | 			 * &ewq->wq may be queued in fork_event, but
  24 | 			 * __remove_wait_queue ignores the head
  25 | 			 * parameter. It would be a problem if it
  26 | 			 * didn't.
  27 | 			 */
  28 | 			__remove_wait_queue(&ctx->event_wqh, &ewq->wq);
  29 | 			if (ewq->msg.event == UFFD_EVENT_FORK) {
  30 | 				struct userfaultfd_ctx *new;
  31 | 
  32 | 				new = (struct userfaultfd_ctx *)
  33 | 					(unsigned long)
  34 | 					ewq->msg.arg.reserved.reserved1;
  35 | 
  36 | 				userfaultfd_ctx_put(new);
  37 | 			}
  38 | 			break;
  39 | 		}
  40 | 
  41 | 		spin_unlock(&ctx->event_wqh.lock);
  42 | 
