   1 | process_bitmap_updates(STREAM s)
   2 | {
   3 | 	uint16 num_updates;
   4 | 	uint16 left, top, right, bottom, width, height;
   5 | 	uint16 cx, cy, bpp, Bpp, compress, bufsize, size;
   6 | 	uint8 *data, *bmpdata;
   7 | 	int i;
   8 | 
   9 | 	logger(Protocol, Debug, "%s()", __func__);
  10 | 
  11 | 	in_uint16_le(s, num_updates);
  12 | 
  13 | 	for (i = 0; i < num_updates; i++)
  14 | 	{
  15 | 		in_uint16_le(s, left);
  16 | 		in_uint16_le(s, top);
  17 | 		in_uint16_le(s, right);
  18 | 		in_uint16_le(s, bottom);
  19 | 		in_uint16_le(s, width);
  20 | 		in_uint16_le(s, height);
  21 | 		in_uint16_le(s, bpp);
  22 | 		Bpp = (bpp + 7) / 8;
  23 | 		in_uint16_le(s, compress);
  24 | 		in_uint16_le(s, bufsize);
  25 | 
  26 | 		cx = right - left + 1;
  27 | 		cy = bottom - top + 1;
  28 | 
  29 | 		logger(Graphics, Debug,
  30 | 		       "process_bitmap_updates(), [%d,%d,%d,%d], [%d,%d], bpp=%d, compression=%d",
  31 | 		       left, top, right, bottom, width, height, Bpp, compress);
  32 | 
  33 | 		if (!compress)
  34 | 		{
  35 | 			int y;
  36 | 			bmpdata = (uint8 *) xmalloc(width * height * Bpp);
  37 | 			for (y = 0; y < height; y++)
  38 | 			{
  39 | 				in_uint8a(s, &bmpdata[(height - y - 1) * (width * Bpp)],
  40 | 					  width * Bpp);
  41 | 			}
  42 | 			ui_paint_bitmap(left, top, cx, cy, width, height, bmpdata);
  43 | 			xfree(bmpdata);
  44 | 			continue;
  45 | 		}
  46 | 
  47 | 
  48 | 		if (compress & 0x400)
  49 | 		{
  50 | 			size = bufsize;
  51 | 		}
  52 | 		else
  53 | 		{
  54 | 			in_uint8s(s, 2);	/* pad */
  55 | 			in_uint16_le(s, size);
  56 | 			in_uint8s(s, 4);	/* line_size, final_size */
  57 | 		}
  58 | 		in_uint8p(s, data, size);
  59 | 		bmpdata = (uint8 *) xmalloc(width * height * Bpp);
  60 | 		if (bitmap_decompress(bmpdata, width, height, data, size, Bpp))
  61 | 		{
  62 | 			ui_paint_bitmap(left, top, cx, cy, width, height, bmpdata);
  63 | 		}
  64 | 		else
  65 | 		{
  66 | 			logger(Graphics, Warning,
  67 | 			       "process_bitmap_updates(), failed to decompress bitmap");
  68 | 		}
  69 | 
  70 | 		xfree(bmpdata);
  71 | 	}
  72 | }
