  17 | 			if (bidder->bid != NULL) {
  18 | 				bid = (bidder->bid)(bidder, a->filter);
  19 | 				if (bid > best_bid) {
  20 | 					best_bid = bid;
  21 | 					best_bidder = bidder;
  22 | 				}
  23 | 			}
  24 | 		}
  25 | 
