  27 | 		if (best_bidder == NULL) {
  28 | 			/* Verify the filter by asking it for some data. */
  29 | 			__archive_read_filter_ahead(a->filter, 1, &avail);
  30 | 			if (avail < 0) {
  31 | 				__archive_read_close_filters(a);
  32 | 				__archive_read_free_filters(a);
  33 | 				return (ARCHIVE_FATAL);
  34 | 			}
  35 | 			a->archive.compression_name = a->filter->name;
  36 | 			a->archive.compression_code = a->filter->code;
  37 | 			return (ARCHIVE_OK);
