  34 |   std::deque<std::pair<string, int>> dir_q;
  35 |   std::deque<std::pair<string, int>> next_dir_q;
  36 |   dir_q.emplace_back(std::make_pair(dirs[0], 0));
  37 |   Status ret;  // Status to return.
  38 |   mutex results_mutex;
  39 |   condition_variable results_cond;
  40 |   mutex next_que_mutex;
  41 |   condition_variable next_que_cond;
  42 |   while (!dir_q.empty()) {
  43 |     next_dir_q.clear();
  44 |     std::vector<Status> new_rets(dir_q.size());
  45 |     auto handle_level = [fs, &results, &dir_q, &next_dir_q, &new_rets,
  46 |                          &is_directory, &dirs, &results_mutex, &results_cond,
  47 |                          &next_que_mutex, &next_que_cond](int i) {
