  82 | 
  83 |       for (size_t j = 0; j < children.size(); ++j) {
  84 |         const string child_path = io::JoinPath(current_dir, children[j]);
  85 |         // If the IsDirectory call was cancelled we bail.
  86 |         if (children_dir_status[j].code() == tensorflow::error::CANCELLED) {
