  15 | 
  16 | 	sc_log(ctx, "read file '%s'; verify_pin:%i", in_path, verify_pin);
  17 | 
  18 | 	*out = NULL;
  19 | 	*out_len = 0;
  20 | 
  21 | 	sc_format_path(in_path, &path);
  22 | 	rv = sc_select_file(card, &path, &file);
  23 | 	if (rv != SC_SUCCESS) {
  24 | 		sc_file_free(file);
  25 | 		LOG_TEST_RET(ctx, rv, "Cannot select oberthur file to read");
  26 | 	}
  27 | 
  28 | 	if (file->ef_structure == SC_FILE_EF_TRANSPARENT)
  29 | 		sz = file->size;
  30 | 	else
  31 | 		sz = (file->record_length + 2) * file->record_count;
  32 | 
  33 | 	*out = calloc(sz, 1);
  34 | 	if (*out == NULL) {
  35 | 		sc_file_free(file);
  36 | 		LOG_TEST_RET(ctx, SC_ERROR_OUT_OF_MEMORY, "Cannot read oberthur file");
  37 | 	}
  38 | 
  39 | 	if (file->ef_structure == SC_FILE_EF_TRANSPARENT)   {
  40 | 		rv = sc_read_binary(card, 0, *out, sz, 0);
  41 | 	}
  42 | 	else	{
  43 | 		int rec;
  44 | 		int offs = 0;
  45 | 		int rec_len = file->record_length;
  46 | 
  47 | 		for (rec = 1; ; rec++)   {
  48 | 			rv = sc_read_record(card, rec, *out + offs + 2, rec_len, SC_RECORD_BY_REC_NR);
  49 | 			if (rv == SC_ERROR_RECORD_NOT_FOUND)   {
  50 | 				rv = 0;
  51 | 				break;
  52 | 			}
  53 | 			else if (rv < 0)   {
  54 | 				break;
  55 | 			}
  56 | 
  57 | 			rec_len = rv;
  58 | 
  59 | 			*(*out + offs) = 'R';
  60 | 			*(*out + offs + 1) = rv;
  61 | 
  62 | 			offs += rv + 2;
  63 | 		}
  64 | 
  65 | 		sz = offs;
  66 | 	}
  67 | 
  68 | 	sc_log(ctx, "read oberthur file result %i", rv);
  69 | 	if (verify_pin && rv == SC_ERROR_SECURITY_STATUS_NOT_SATISFIED)   {
  70 | 		struct sc_pkcs15_object *objs[0x10], *pin_obj = NULL;
  71 | 		const struct sc_acl_entry *acl = sc_file_get_acl_entry(file, SC_AC_OP_READ);
  72 | 		int ii;
