  74 | 		rv = sc_pkcs15_get_objects(p15card, SC_PKCS15_TYPE_AUTH_PIN, objs, 0x10);
  75 | 		if (rv != SC_SUCCESS) {
  76 | 			sc_file_free(file);
  77 | 			LOG_TEST_RET(ctx, rv, "Cannot read oberthur file: get AUTH objects error");
