  83 | 					auth_info->attrs.pin.reference, acl->key_ref, auth_info->auth_method, acl->method);
  84 | 			if (auth_info->attrs.pin.reference == (int)acl->key_ref && auth_info->auth_method == (unsigned)acl->method)   {
  85 | 				pin_obj = objs[ii];
