  31 | 		iov = sock_kmalloc(sock->sk, iov_size, GFP_KERNEL);
  32 | 		if (!iov)
  33 | 			goto out;
  34 | 	}
  35 | 
  36 | 	/* This will also move the address data into kernel space */
  37 | 	if (MSG_CMSG_COMPAT & flags) {
  38 | 		err = verify_compat_iovec(msg_sys, iov,
  39 | 					  (struct sockaddr *)&address,
  40 | 					  VERIFY_READ);
  41 | 	} else
  42 | 		err = verify_iovec(msg_sys, iov,
  43 | 				   (struct sockaddr *)&address,
  44 | 				   VERIFY_READ);
