  61 | 		ctl_len = msg_sys->msg_controllen;
  62 | 	} else if (ctl_len) {
  63 | 		if (ctl_len > sizeof(ctl)) {
  64 | 			ctl_buf = sock_kmalloc(sock->sk, ctl_len, GFP_KERNEL);
