   1 | int gdAlphaBlend (int dst, int src) {
   2 |     int src_alpha = gdTrueColorGetAlpha(src);
   3 |     int dst_alpha, alpha, red, green, blue;
   4 |     int src_weight, dst_weight, tot_weight;
   5 | 
   6 | /* -------------------------------------------------------------------- */
   7 | /*      Simple cases we want to handle fast.                            */
   8 | /* -------------------------------------------------------------------- */
   9 |     if( src_alpha == gdAlphaOpaque )
  10 |         return src;
  11 | 
  12 |     dst_alpha = gdTrueColorGetAlpha(dst);
  13 |     if( src_alpha == gdAlphaTransparent )
  14 |         return dst;
  15 |     if( dst_alpha == gdAlphaTransparent )
  16 |         return src;
  17 | 
  18 | /* -------------------------------------------------------------------- */
  19 | /*      What will the source and destination alphas be?  Note that      */
  20 | /*      the destination weighting is substantially reduced as the       */
  21 | /*      overlay becomes quite opaque.                                   */
  22 | /* -------------------------------------------------------------------- */
  23 |     src_weight = gdAlphaTransparent - src_alpha;
  24 |     dst_weight = (gdAlphaTransparent - dst_alpha) * src_alpha / gdAlphaMax;
  25 |     tot_weight = src_weight + dst_weight;
  26 |     
  27 | /* -------------------------------------------------------------------- */
  28 | /*      What red, green and blue result values will we use?             */
  29 | /* -------------------------------------------------------------------- */
  30 |     alpha = src_alpha * dst_alpha / gdAlphaMax;
  31 | 
  32 |     red = (gdTrueColorGetRed(src) * src_weight
  33 |            + gdTrueColorGetRed(dst) * dst_weight) / tot_weight;
  34 |     green = (gdTrueColorGetGreen(src) * src_weight
  35 |            + gdTrueColorGetGreen(dst) * dst_weight) / tot_weight;
  36 |     blue = (gdTrueColorGetBlue(src) * src_weight
  37 |            + gdTrueColorGetBlue(dst) * dst_weight) / tot_weight;
  38 | 
  39 | /* -------------------------------------------------------------------- */
  40 | /*      Return merged result.                                           */
  41 | /* -------------------------------------------------------------------- */
  42 |     return ((alpha << 24) + (red << 16) + (green << 8) + blue);
