  10 | 		       grub_off_t filesize, int log2blocksize)
  11 | {
  12 |   grub_disk_addr_t i, blockcnt;
  13 |   int blocksize = 1 << (log2blocksize + GRUB_DISK_SECTOR_BITS);
  14 | 
  15 |   /* Adjust LEN so it we can't read past the end of the file.  */
  16 |   if (pos + len > filesize)
  17 |     len = filesize - pos;
  18 | 
  19 |   if (len < 1 || len == 0xffffffff) {
  20 |     return -1;
  21 |   }
  22 | 
  23 |   blockcnt = ((len + pos) + blocksize - 1) >>
  24 |     (log2blocksize + GRUB_DISK_SECTOR_BITS);
  25 | 
  26 |   for (i = pos >> (log2blocksize + GRUB_DISK_SECTOR_BITS); i < blockcnt; i++)
  27 |     {
  28 |       grub_disk_addr_t blknr;
  29 |       int blockoff = pos & (blocksize - 1);
  30 |       int blockend = blocksize;
  31 | 
  32 |       int skipfirst = 0;
  33 | 
  34 |       blknr = get_block (node, i);
  35 |       if (grub_errno)
  36 | 	return -1;
  37 | 
  38 |       blknr = blknr << log2blocksize;
  39 | 
  40 |       /* Last block.  */
  41 |       if (i == blockcnt - 1)
  42 | 	{
  43 | 	  blockend = (len + pos) & (blocksize - 1);
  44 | 
  45 | 	  /* The last portion is exactly blocksize.  */
  46 | 	  if (! blockend)
  47 | 	    blockend = blocksize;
  48 | 	}
  49 | 
  50 |       /* First block.  */
  51 |       if (i == (pos >> (log2blocksize + GRUB_DISK_SECTOR_BITS)))
  52 | 	{
  53 | 	  skipfirst = blockoff;
  54 | 	  blockend -= skipfirst;
  55 | 	}
  56 | 
  57 |       /* If the block number is 0 this block is not stored on disk but
  58 | 	 is zero filled instead.  */
  59 |       if (blknr)
  60 | 	{
  61 | 	  disk->read_hook = read_hook;
  62 | 	  disk->closure = closure;
  63 | 
  64 | //printf ("blknr: %d\n", blknr);
  65 | grub_hack_lastoff = blknr * 512;
