   2 | {
   3 | 	struct inet_peer __rcu **stack[PEER_MAXDEPTH], ***stackptr;
   4 | 	struct inet_peer_base *base = family_to_base(daddr->family);
   5 | 	struct inet_peer *p;
   6 | 	unsigned int sequence;
