  10 | 	 * Because of a concurrent writer, we might not find an existing entry.
  11 | 	 */
  12 | 	rcu_read_lock();
  13 | 	sequence = read_seqbegin(&base->lock);
  14 | 	p = lookup_rcu(daddr, base);
  15 | 	invalidated = read_seqretry(&base->lock, sequence);
  16 | 	rcu_read_unlock();
  17 | 
  18 | 	if (p)
  19 | 		return p;
  20 | 
  21 | 	/* If no writer did a change during our lookup, we can return early. */
  22 | 	if (!create && !invalidated)
  23 | 		return NULL;
  24 | 
  25 | 	/* retry an exact lookup, taking the lock before.
  26 | 	 * At least, nodes should be hot in our cache.
  27 | 	 */
  28 | 	write_seqlock_bh(&base->lock);
  29 | relookup:
  30 | 	p = lookup(daddr, stack, base);
  31 | 	if (p != peer_avl_empty) {
  32 | 		atomic_inc(&p->refcnt);
  33 | 		write_sequnlock_bh(&base->lock);
  34 | 		return p;
  35 | 	}
  36 | 	if (!gccnt) {
  37 | 		gccnt = inet_peer_gc(base, stack, stackptr);
  38 | 		if (gccnt && create)
  39 | 			goto relookup;
  40 | 	}
  41 | 	p = create ? kmem_cache_alloc(peer_cachep, GFP_ATOMIC) : NULL;
  42 | 	if (p) {
  43 | 		p->daddr = *daddr;
  44 | 		atomic_set(&p->refcnt, 1);
  45 | 		atomic_set(&p->rid, 0);
  46 | 		atomic_set(&p->ip_id_count, secure_ip_id(daddr->addr.a4));
  47 | 		p->tcp_ts_stamp = 0;
  48 | 		p->metrics[RTAX_LOCK-1] = INETPEER_METRICS_NEW;
  49 | 		p->rate_tokens = 0;
  50 | 		p->rate_last = 0;
  51 | 		p->pmtu_expires = 0;
  52 | 		p->pmtu_orig = 0;
  53 | 		memset(&p->redirect_learned, 0, sizeof(p->redirect_learned));
